{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "Salmeterol, the closest analogue (Morgan 0.678) sharing the same 4-hydroxy-3-hydroxymethylphenylethanolamine head and long aminoalkyl ether chain, has an oral bioavailability of about 1% in patients, directly supporting a low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "The R-enantiomer of salbutamol, which shares the same phenolic head group, has only 9% oral bioavailability due to intestinal and hepatic sulfation; this supports low F for the query, although the query's long-chain substitution is more similar to salmeterol.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Racemic salbutamol has an absolute oral bioavailability of 44% in healthy volunteers, but it lacks the long lipophilic aminoalkyl chain and dichlorobenzyl ether of the query, so this high-F evidence is only weakly transferable and does not outweigh the salmeterol anchor.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a vilanterol-like long-chain beta2 agonist. The closest analogue salmeterol has ~1% oral bioavailability, and the same phenolic head group undergoes extensive first-pass conjugation (R-salbutamol 9%). Although racemic salbutamol shows ~44% oral bioavailability, it lacks the long lipophilic chain that drives low systemic exposure in this series. Overall, F < 20% is better supported.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for the exact query molecule is present; the closest direct evidence is salmeterol at ~1%.",
    "The effect of the 2,6-dichlorobenzyl and extra ethylene glycol ether on first-pass metabolism and absorption is not directly quantified."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

